{"code": "import pytest

import impl


def test_empty_input_returns_empty_list():
    assert impl.merge_bookings([]) == []


def test_single_booking_returned_unchanged():
    assert impl.merge_bookings([(60, 120)]) == [(60, 120)]


def test_non_overlapping_non_touching_stay_separate():
    result = impl.merge_bookings([(60, 120), (121, 180)])
    assert result == [(60, 120), (121, 180)]


def test_touching_intervals_merge_into_one_block():
    result = impl.merge_bookings([(60, 120), (120, 180)])
    assert result == [(60, 180)]


def test_overlapping_intervals_merge():
    result = impl.merge_bookings([(60, 130), (100, 180)])
    assert result == [(60, 180)]


def test_nested_interval_absorbed():
    result = impl.merge_bookings([(60, 300), (120, 180)])
    assert result == [(60, 300)]


def test_exact_duplicates_collapse_to_one_block():
    result = impl.merge_bookings([(60, 120), (60, 120)])
    assert result == [(60, 120)]


def test_zero_width_entry_dropped_and_does_not_bridge_gap():
    result = impl.merge_bookings([(0, 60), (90, 90), (120, 180)])
    assert result == [(0, 60), (120, 180)]


def test_all_zero_width_entries_yield_empty_list():
    result = impl.merge_bookings([(5, 5), (10, 10), (-3, -3)])
    assert result == []


def test_negative_minutes_touching_pair_merges():
    result = impl.merge_bookings([(-60, 0), (0, 60)])
    assert result == [(-60, 60)]


def test_unsorted_input_is_sorted_in_output():
    result = impl.merge_bookings([(700, 720), (480, 540), (600, 630)])
    assert result == [(480, 540), (600, 630), (700, 720)]


def test_list_entries_accepted_and_output_is_tuples():
    result = impl.merge_bookings([[60, 120], [120, 180]])
    assert result == [(60, 180)]
    for block in result:
        assert isinstance(block, tuple)
        assert isinstance(block[0], int) and isinstance(block[1], int)


def test_worked_example_from_ticket():
    result = impl.merge_bookings(
        [(540, 600), (600, 630), (630, 630), (700, 720), (690, 700), (480, 540)]
    )
    assert result == [(480, 630), (690, 720)]


def test_input_list_and_entries_not_mutated():
    original_entries = [(700, 720), (480, 540)]
    intervals = list(original_entries)
    snapshot = list(intervals)
    impl.merge_bookings(intervals)
    assert intervals == snapshot
    for entry in intervals:
        assert isinstance(entry, tuple)


def test_start_greater_than_end_raises_value_error_with_pair_in_message():
    with pytest.raises(ValueError) as excinfo:
        impl.merge_bookings([(120, 60)])
    assert "(120, 60)" in str(excinfo.value)


def test_start_equals_end_is_not_an_error():
