    ],
)
def test_non_int_elements_raise_value_error(bad_entry):
    with pytest.raises(ValueError):
        impl.merge_bookings([bad_entry])


def test_result_blocks_are_pairwise_non_touching_and_sorted():
    result = impl.merge_bookings(
        [(-60, 60), (10, 20), (200, 300), (300, 300), (350, 400), (150, 200)]
    )
